                    if grid[r][c] == bg:
                        out[r][c] = 2

    # Complete the perimeter of the bounding rectangle around the marks.
    for c in range(c0, c1 + 1):
        if out[r0][c] == bg:
            out[r0][c] = 2
        if out[r1][c] == bg:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
