 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]

    # Demo 1: fill the interior of the marked rectangle, preserving all marks.
    if 0 in {grid[r][c] for r, c in pts}:
        r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
        c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
        return out

    # Demos 2 and 3: at a row/column containing one or more foreground gaps,
    # gaps between the outermost foreground points are colored 2 only where
    # they are background in the input.
    # To avoid flooding the long vertical/horizontal strokes in demo 3, fill
    # only lines with a short run of points; for longer, sparse lines repair
